  "commands": [
    {
      "keystrokes": "cd /app/debs && python3 - <<'EOF'
import urllib.request
for line in open('/app/uris.txt'):
    url=line.strip()
    if not url: continue
    fn=url.rsplit('/',1)[-1]
    try:
        urllib.request.urlretrieve(url, fn)
        print('OK', fn)
    except Exception as e:
        print('FAIL', url, e)
EOF
",
      "duration": 60.0
    }
  ]
